  envVar: "OPENAI_API_KEY" | "ANTHROPIC_API_KEY" | "GOOGLE_GENERATIVE_AI_API_KEY" | "OPENROUTER_API_KEY"
): string {
  const key = process.env[envVar]?.trim();
