import { tool } from "ai";
import { z } from "zod";

// Composio integration stub - will call Composio API when keys present
// For now provides a generic "composio action" tool that lists available apps
// and executes actions via Composio's API.

const composioActionSchema = z.object({
  app: z.string().describe("Composio app slug, e.g. 'metaads', 'googleads', 'gmail', 'notion'"),
  action: z.string().describe("Action name within the app, e.g. 'METAADS_CREATE_CAMPAIGN'"),
  params: z.record(z.string(), z.unknown()).optional().describe("Parameters for the action"),
});

export const composioTool = tool({
  description:
    "Execute a Composio connected-app action. Use when user wants to interact with marketing platforms (Meta Ads, Google Ads, etc.). Requires COMPOSIO_API_KEY and a connected account. If not configured, explain what would happen.",
  inputSchema: composioActionSchema,
  execute: async ({ app, action, params }) => {
    const apiKey = process.env.COMPOSIO_API_KEY?.trim();
    if (!apiKey) {
      return {
        success: false,
        message: `COMPOSIO_API_KEY not configured. Would have executed ${app}.${action} with params: ${JSON.stringify(params ?? {}, null, 2)}. Add COMPOSIO_API_KEY and connect accounts at https://app.composio.dev to enable.`,
        requiresSetup: true,
      };
    }

    // If key present, try to call Composio Tool Router / execute
    // This is a minimal implementation - full flow uses @composio/core SDK with entityId
    try {
      // Dynamically import to avoid bundling issues if not installed correctly
      const { Composio } = await import("@composio/core");
      const composio = new Composio({ apiKey });

      // For now use the generic execute - in production you'd use:
      // composio.tools.execute({ action, params, entityId: userId })
      // We'll attempt a lightweight tools list check first
      const tools = await (composio.tools as unknown as { getRawComposioTools?: (q: unknown) => Promise<unknown> }).getRawComposioTools?.({ toolkits: [app] } as unknown as never).catch(() => null);
      if (!tools) {
        return {
          success: false,
          message: `Action ${action} not found for app ${app}. Check available actions at https://app.composio.dev/apps/${app}`,
        };
      }

      return {
        success: true,
        message: `Composio tool ${action} found. To execute with user context, connect accounts and provide entityId. Params: ${JSON.stringify(params ?? {})}`,
        tool: tools,
      };
    } catch (error) {
      const msg = error instanceof Error ? error.message : String(error);
      return {
        success: false,
        message: `Composio execution failed: ${msg}. App: ${app}, Action: ${action}`,
      };
    }
  },
});

// Helper to list available composio apps (for model to discover)
export const composioListAppsTool = tool({
  description: "List available Composio apps/integrations that can be used for marketing execution.",
  inputSchema: z.object({}),
  execute: async () => {
    const apiKey = process.env.COMPOSIO_API_KEY?.trim();
    if (!apiKey) {
      return {
